class Solution:
    def assignTasks(self, servers: list[int], tasks: list[int]) -> list[int]:
        time = 0
        free = list(range(len(servers)))
        busy = []
        ans = []
        for j, duration in enumerate(tasks):
            time = max(time, j)
            changed = True
            while changed:
                changed = False
                remaining = []
                for finish, idx in busy:
                    if finish <= time:
                        free.append(idx)
                        changed = True
                    else:
                        remaining.append((finish, idx))
                busy = remaining
            if not free:
                time = min(finish for finish, _ in busy)
                remaining = []
                for finish, idx in busy:
                    if finish <= time:
                        free.append(idx)
                    else:
                        remaining.append((finish, idx))
                busy = remaining
            best = min(free, key=lambda i: (servers[i], i))
            free.remove(best)
            ans.append(best)
            busy.append((time + duration, best))
        return ans

